 "content": "from collections import Counter


def _mode(seq):
    return Counter(seq).most_common(1)[0][0]


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The repeated, non-background separator rows/columns form the lattice
    # vertices.  Their intersections encode the four corners of each output
    # tile.
    rlines = [r for r, row in enumerate(grid) if _mode(row) != background]
    clines = [c for c in range(w) if _mode([grid[r][c] for r in range(h)]) != background]

    if len(rlines) < 2 or len(clines) < 2:
        raise ValueError('could not identify separator lattice')

    out = []
    for r0, r1 in zip(rlines, rlines[1:]):
        row_out = []
        for c0, c1 in zip(clines, clines[1:]):
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            row_out.append(corners[0] if all(v == corners[0] for v in corners) else background)
        out.append(row_out)

    # Empty-background margins carry no encoded feature and are not part of
    # the compact result.
    while out and all(v == background for v in out[0]):
        out.pop(0)
    while out and all(v == background for v in out[-1]):
        out.pop()
    if out:
        while out[0] and all(row[0] == background for row in out):
            for row in out:
                row.pop(0)
        while out[0] and all(row[-1] == background for row in out):
            for row in out:
                row.pop()
    return out


